ox-shadow:0 12px 44px rgba(15,23,42,.12);font-family:'Segoe UI',Roboto,Helvetica,Arial,sans-serif"><tr><td style="background:linear-gradient(135deg,${brand.colorDark} 0%,${brand.color} 100%);padding:34px 24px 30px" align="center">${logoBlock}<h1 style="margin:20px 0 0;color:#ffffff;font-size:23px;font-weight:800;letter-spacing:-.02em">${title}</h1>${subtitle?`<p style="margin:9px 0 0;color:rgba(255,255,255,.88);font-size:14px;font-weight:500">${subtitle}</p>`:''}</td></tr><tr><td style="padding:34px 32px 10px;color:#334155;font-size:15px;line-height:1.65">${bodyHtml}</td></tr>${cta}<tr><td style="padding:30px 32px 32px"><table role="presentation" width="100%"><tr><td style="border-top:1px solid #eef2f6;padding-top:20px"><p style="margin:0;color:#64748b;font-size:13px;font-weight:700">${brand.name}</p><p style="margin:4px 0 0;color:#94a3b8;font-size:12px;line-height:1.6">${footerNote}</p></td></tr></table></td></tr></table><p style="margin:18px 0 0;color:#cbd5e1;font-size:11px">© ${year} ${brand.name} — ${copyright}</p></td></tr></table></body></html>`; }
function detailTable(rows) { const trs=rows.filter(Boolean).map(([label,value])=>`<tr><td style="padding:12px 16px;background:#f8fafc;border-bottom:1px solid #eef2f6;font-weight:600;color:#475569;font-size:13px;width:38%">${label}</td><td style="padding:12px 16px;border-bottom:1px solid #eef2f6;color:#0f172a;font-size:14px;font-weight:500">${value}</td></tr>`).join(''); return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:separate;border-spacing:0;border:1px solid #eef2f6;border-radius:12px;overflow:hidden;margin:20px 0">${trs}</table>`; }
const d = body;
const table = detailTable([[isEn?'Candidate':'Candidat',d.candidat_nom],['Email',d.candidat_email||'—'],[isEn?'Phone':'Téléphone',d.candidat_telephone||'—'],[isEn?'Position':'Poste',d.titre_poste]]);
const note = isEn ? `<p style="margin:16px 0 0;color:#64748b;font-size:13px">You may contact the candidate directly or archive their application.</p>` : `<p style="margin:16px 0 0;color:#64748b;font-size:13px">Vous pouvez prendre contact directement avec le candidat ou archiver sa candidature.</p>`;
const bodyHtml = isEn
  ? `<p style="margin:0 0 14px">The candidate <strong>${d.candidat_nom}</strong> has not booked an interview for the <strong>${d.titre_poste}</strong> position after 2 reminders.</p>${table}${note}`
  : `<p style="margin:0 0 14px">Le candidat <strong>${d.candidat_nom}</strong> n'a pas pris de rendez-vous pour le poste de <strong>${d.titre_poste}</strong> après 2 relances.</p>${table}${note}`;
const from = `"${fromName}" <dtb@solumada.mg>`;
return [{ json: { from, to: d.email_recruteur, subject: isEn?`⚠️ No booking — ${d.candidat_nom} / ${d.titre_poste}`:`⚠️ Aucun RDV — ${d.candidat_nom} / ${d.titre_poste}`, html: emailLayout({ preheader: isEn?`${d.candidat_nom} did not book after 2 reminders`:`${d.candidat_nom} n'a pas pris de RDV après 2 relances`, title: isEn?'No Booking ⚠️':'Absence de réservation ⚠️', subtitle: d.candidat_nom, bodyHtml }) }}];

const body = $('01 - Candidate Webhook').first().json.body;
const email = body.candidat_email.toLowerCase();
const lienRdv = body.lien_rdv || '';
const slugParts = lienRdv.replace(/\/$/, '').split('/').filter(Boolean);
const expectedSlug = slugParts.length >= 2 ? slugParts[slugParts.length - 1] : '';
const bookings = $input.first().json.data.bookings || [];
const rdv = bookings.some(b =>
  (b.status === 'ACCEPTED' || b.status === 'PENDING') &&
  (b.attendees || []).some(a => a.email?.toLowerCase() === email) &&
  (!expectedSlug || (b.eventType?.slug || b.eventTypeSlug || '') === expectedSlug)
);
return [{ json: { rdv_trouve: rdv } }];
